class ValidatorChainField(forms.CharField):
    def run_validators(self, value):
        errors = []
        for validator in self.validators:
            try:
                validator(value)
            except forms.ValidationError as e:
                errors.extend(e.messages)
        if errors:
            raise forms.ValidationError(errors)

